type Parsed = { kind: 'empty' } | { kind: 'bad' } | { kind: 'ok'; scaled: bigint };

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function emptyMaterial(): MaterialLine {
  return { maVt: '', tenVt: '', dvt: '', soLuong: '', gia: '0', tien: '0' };
}

function emptyStage(): StageLine {
  return { maCdI: '', tenCdI: '', soLuong: '', tg: '', tienNt: '', tien: '0' };
}

